class RuleOfZero {
  // No user-declared special members.
  // Compiler generates default/copy/move/destructor.
  std::string s;
};

class SuppressedMove {
public:
  ~SuppressedMove() {} // User-declared destructor

  // Because of the destructor, the compiler will NOT generate
  // a move constructor or move assignment operator.
  // This class is copyable but not movable.
private:
  std::string s;
};
